/bin/zsh -lc "python3 - <<'PY'
import json,re,hashlib,collections
from html import unescape
from html.parser import HTMLParser
from pathlib import Path
s=json.loads(Path('source.json').read_text());a=json.loads(Path('answer.json').read_text());r=json.loads(Path('reference-targets.json').read_text())
assert len(s)==len(a)==24
allowed={'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
classes={'material_reduction','coordination_only','retained_necessary','financing_transfer','payment_timing_relief','mixed','reserved','editorial_only'}
kinds={'tax_removed','tax_reduced','obligation_removed','obligation_merged','authorization_removed','regime_merged','deadline_reduced','compliance_cost_reduced','tax_increased','obligation_added','deadline_increased','complexity_added','financing_transfer','payment_deferred','relief_extended','relief_preserved','coordination'}
units={'percent','euro','legal_duty','regime','calendar_days','working_days','financing','other'}
class Validate(HTMLParser):
 def handle_starttag(self,tag,attrs):
  assert tag in allowed,tag
  for k,v in attrs:assert k in ('rowspan','colspan') and v.isdigit(),(tag,k,v)
def plain(t):return unescape(re.sub(r'<["'^>]*>'"','',t or ''))
for x,y in zip(s,a):
 n=x['number']
 for k in ['code_id','source_id','source_sha256','number']:assert x[k]==y[k],(n,k)
 for k in ['reason','review_notes','status','proposed_xml','substantive_impact']:assert k in y,(n,k)
 imp=y['substantive_impact'];assert imp['version']==1 and imp['classification'] in classes
 for k in ['assessment','scope_limitations','new_burdens_review']:assert len(imp[k])>=40,(n,k)
 if x.get('benefit_check_required'):assert len(y['benefit_review'])>=100,n
 if y['status']=='retained_unchanged':
  assert y['proposed_xml'] is None and y['classification']=='retained_necessary'
  assert imp['classification']=='retained_necessary' and imp['effects']==[]
 else:
  assert y['status']=='rewrite_draft' and y['proposed_xml']
  Validate().feed(y['proposed_xml'])
 if y.get('change_type')=='normative_reduction':
  assert y['reform_policy_id']=='editorial_direction_2026_10_19'
  assert all(len(t)>=30 for t in y['removed_provisions'])
 for e in imp['effects']:
  assert e['kind'] in kinds and e['unit'] in units
  assert re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*',e['measure_id']) and 6<=len(e['measure_id'])<=96
  assert set(e)=={'kind','measure_id','description','before','after','unit','affected_population','conditions_and_transition','replacement_or_new_burdens','source_quote','proposed_quote'}
  for k,t in [('source_quote',plain(x['source_xml'])),('proposed_quote',plain(y['proposed_xml']))]:
   assert len(e[k])>=12 and e[k] in t,(n,k,e[k])
 key=x['code_id']+'|'+x['source_id'];checks=y['reference_checks'];req=r['requirements'][key]
 assert [v['target_key'] for v in checks]==req,(n,'targets')
 for c in checks:
  assert c['view_sha256']==r['targets'][c['target_key']]['view_sha256'] and len(c['assessment'])>=80
for x in s:
 key=x['code_id']+'|'+x['source_id']
 if key in r['referrers']:
  meta=r['referrers'][key]
  for field,hashfield in [('source_xml','source_xml_sha256'),('source_notes_xml','source_notes_sha256')]:assert hashlib.sha256(x[field].encode()).hexdigest()==meta[hashfield]
print('Validation structurelle : 24 sources, identifiants et citations exacts, balises autorisées, analyses et cibles de renvoi conformes.')
print('Statuts :',dict(collections.Counter(x['status'] for x in a)))
print('Impacts :',dict(collections.Counter(x['substantive_impact']['classification'] for x in a)))
print('Références :',sum(len(x['reference_checks']) for x in a))
print('Empreinte answer.json :',hashlib.sha256(Path('answer.json').read_bytes()).hexdigest())
PY"

